// Console — the page that STARTS AND HOSTS SYSTEM SESSIONS (`system-sessions-run-projects-and-start-when-visited`),
// AS GRAPH SOURCE. A system session runs a project or application for the user — the tutors first — and the
// console lists every one, starts one only when the user opens it, and hosts its terminal. Whether a session is
// running is OBSERVED from the PTY host on each read, never stored; a session nobody is using is reaped, and
// reopening it continues its conversation because its directory is fixed.
//
// THE PROJECT TABS ARE NOT SHOWN, AND STILL MOUNTED. Moving project fleet panes out of the console is the next
// slice (`project-fleet-panes-live-only-in-glance`). Until it lands, each persisted tab keeps its hidden
// `primary` claim so a fleet terminal Glance shows is still launched the way it was — removing the claims
// here, before Glance owns them, would break fleet launching. A torn-off window (`tabIdxOverride`) still pins
// and shows its own tab exactly as before.
import { useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { recordRender } from "@/shared/lib/core/perf";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { useConsolePumps } from "@/app/console/useConsolePumps";
import { useDirectorPump } from "@/app/console/useDirectorPump";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Button } from "@/shared/ui/controls/Button";
import { Text } from "@/shared/ui/typography/Text";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { useScreenDescriptor } from "@/shared/hooks/useScreenDescriptor";
import { useSystemSessionViewer } from "@/features/studio-sessions";
import { SYSTEM_SESSIONS, systemSessionDef } from "@/shared/lib/session/systemSessionDefs";
import { readPaneRuntimes, isPaneWorking, isPanePresent } from "@/shared/lib/session/paneRuntimeRead";

/** How often the console re-reads what the PTY host says about each system session while it is showing. */
const SYSTEM_SESSION_STATUS_MS = 3000;

export function ConsoleWorkspace({ tabIdxOverride }: { tabIdxOverride?: number } = {}) {
  // App-wide pumps live in their own record now; mounted here because ConsoleWorkspace stays mounted
  // across every screen, so the fleet keeps advancing off-screen.
  useConsolePumps();

  const tabs              = useAppStore((s) => s.tabs);
  const storeActiveTabIdx = useAppStore((s) => s.activeTabIdx);
  // A tear-off window pins its OWN tab via tabIdxOverride, decoupled from the shared activeTabIdx.
  const activeTabIdx      = tabIdxOverride ?? storeActiveTabIdx;
  const paneCwds          = useAppStore((s) => s.paneCwds);
  const paneInitCmds      = useAppStore((s) => s.paneInitCmds);
  const setPaneStatus     = useAppStore((s) => s.setPaneStatus);
  const setPaneCwd        = useAppStore((s) => s.setPaneCwd);
  const setFocusedPane    = useAppStore((s) => s.setFocusedPane);
  const activeWorkspace   = useAppStore((s) => s.activeWorkspace);
  const detached          = tabIdxOverride !== undefined;
  // Showing = the main window's console is the active workspace. A hidden console must not keep a session it
  // opened pinned alive, or the reaper could never take it.
  const showing           = !detached && activeWorkspace === "console";

  useEffect(() => { recordRender(); });

  // The director pump is inert since #app-stops-pushing-prompts but is still called; it reads a live
  // pane-status ref. Kept until the record graph drops the call.
  const paneStatuses = useAppStore((s) => s.paneStatus);
  const paneStatusesRef = useRef(paneStatuses);
  useEffect(() => { paneStatusesRef.current = paneStatuses; }, [paneStatuses]);
  useDirectorPump(paneStatusesRef);

  // THE SYSTEM SESSION THE USER OPENED. Opening it is the lazy start: the viewer makes it wanted, its host mount
  // prepares its workspace, and its terminal launches. Local to this view — which session was open is navigation,
  // and nothing about a session's life depends on it.
  const [openId, setOpenId] = useState<string | null>(null);
  const open = systemSessionDef(openId);
  useSystemSessionViewer(open?.id ?? null, showing);

  // WHAT EACH SESSION IS DOING, READ FROM THE PTY HOST while the console is showing. A read that could not run
  // leaves the last answer in place rather than claiming every session stopped.
  const [status, setStatus] = useState<Record<string, "stopped" | "running" | "working">>({});
  useEffect(() => {
    if (!showing) return;
    let alive = true;
    const read = async () => {
      const runtimes = await readPaneRuntimes(SYSTEM_SESSIONS.map((d) => d.paneId));
      if (!alive || runtimes === null) return;
      setStatus(Object.fromEntries(SYSTEM_SESSIONS.map((d) => {
        const view = runtimes.get(d.paneId);
        return [d.id, isPaneWorking(view) ? "working" : isPanePresent(view) ? "running" : "stopped"];
      })));
    };
    void read();
    const timer = setInterval(() => { void read(); }, SYSTEM_SESSION_STATUS_MS);
    return () => { alive = false; clearInterval(timer); };
  }, [showing]);

  // WHAT `bsc app go` CAN SELECT HERE (`the-shared-navigation-mechanism-drill-select-and-show`): each system
  // session, addressed by its PANE id. A torn-off window pins its own tab and publishes nothing, so it cannot
  // answer for the main window's console.
  useScreenDescriptor(
    detached
      ? null
      : {
          workspace: "console",
          layer: "sessions",
          drill: [],
          selection: open?.paneId ?? null,
          targets: SYSTEM_SESSIONS.map((d) => ({ id: d.paneId, label: d.title, drillable: false, selectable: true })),
          select: (id) => {
            const def = systemSessionDef(id);
            if (def) setOpenId(def.id);
          },
        },
  );

  const tabSlots = tabs.map((tab, ti) => {
    const pid = paneIdFor(tab, ti, 0);
    // A torn-off window SHOWS its pinned tab; the main window keeps every tab's claim hidden.
    const visibleTab = detached && ti === activeTabIdx;
    return (
      // A SLOT, not a TerminalView (`a-woken-fleet-worker-has-no-mount-so-wake-spawns-nothing`): the host owns
      // every terminal and this cell is its primary claim.
      <Stack key={pid} style={{ display: visibleTab ? "flex" : "none", flex: 1, minHeight: 0 }}>
        <TerminalSlot
          paneId={pid}
          primary
          visible={visibleTab}
          focused={visibleTab}
          initialCwd={paneCwds[pid]}
          initCmd={paneInitCmds[pid]}
          onStatusChange={(s) => setPaneStatus(pid, s)}
          onCwdChange={(cwd) => setPaneCwd(pid, cwd)}
          onFocus={() => setFocusedPane(0)}
        />
      </Stack>
    );
  });

  if (detached) {
    return <Stack style={{ flex: 1, minHeight: 0, background: "var(--bg-canvas)" }}>{tabSlots}</Stack>;
  }

  return (
    <Stack style={{ flex: 1, minHeight: 0, background: "var(--bg-canvas)" }} data-testid="console-system-sessions">
      <Row wrap style={{ gap: 8, padding: 8 }}>
        {SYSTEM_SESSIONS.map((d) => (
          <Button
            key={d.id}
            variant={open?.id === d.id ? "primary" : "default"}
            aria-pressed={open?.id === d.id}
            data-testid={`system-session-${d.id}`}
            title={d.summary}
            onClick={() => setOpenId(d.id)}
          >
            {d.title} · <Text mono>{d.model}</Text> · {status[d.id] ?? "stopped"}
          </Button>
        ))}
      </Row>
      {open ? (
        <Stack style={{ flex: 1, minHeight: 0 }}>
          <TerminalSlot paneId={open.paneId} visible={showing} focused={showing} />
        </Stack>
      ) : (
        <Text style={{ padding: 16 }}>
          Open a system session to start it. Nothing runs until you do, a session nobody is using is reaped, and
          opening it again continues its conversation.
        </Text>
      )}
      {/* The project tabs' hidden primary claims — see the header. */}
      <Stack aria-hidden style={{ display: "none" }}>{tabSlots}</Stack>
    </Stack>
  );
}

